-- أَنْزَلْنَاهُ (root نزل) word-view blocks — generated. INSERT OR REPLACE (idempotent).

INSERT OR REPLACE INTO qr_morph_display_blocks
 (id, scope_level, scope_key, root_ar, ayah_key, surah_no, ayah_no, word_index,
  block_type, block_subtype, display_order, title_ar, title_en, title_ur,
  text_ar, text_en, text_ur, data_json, source_slug, is_synthesis, register, registers_json, meta_json, status)
 VALUES ('MDB:root:نزل:root_dna', 'root', 'نزل', 'نزل', '44:3', 44, 3, 2,
  'root_dna', NULL, 1, 'الجذر', 'Root DNA', 'جڑ',
  'يردّ ابن فارس مادّة (ن ز ل) إلى أصلٍ صحيحٍ واحد: ==هُبوطُ شيءٍ ووقوعُه==. فنَزَلَ من عُلوٍّ إلى سُفل، ونَزَلَ بالمكان وبالقوم: حلَّ به؛ ومنه إنزالُ الغَيثِ والرزقِ، ثم ==تنزيلُ الوحيِ== هُبوطاً للكلامِ من عند الله.', 'Ibn Fāris fixes the whole root to one sound core: ==the coming-down and alighting== of a thing from a height to a lower place. نَزَلَ “descended,” نَزَلَ بالقوم “lodged among a people.” From that: the sending-down of rain and provision, and finally ==the sending-down of revelation== — speech brought down from God.', 'ابن فارس پورے مادّے کو ایک اصل کی طرف لوٹاتے ہیں: کسی چیز کا اترنا اور واقع ہونا۔ نَزَلَ بلندی سے پستی کی طرف؛ پھر بارش و رزق کا نزول، اور آخرکار وحی کا تنزیل۔', '{"letters":["ن","ز","ل"],"core_ar":"الهُبوطُ والحُلولُ من عُلوٍّ إلى أسفل؛ ثم الإنزالُ والتنزيل","frequency_quran":293}', 'saaid_maqayis_al_lugha', 0, 'classical', '["classical"]', '{"icon":"dna"}', 'live');

INSERT OR REPLACE INTO qr_morph_display_blocks
 (id, scope_level, scope_key, root_ar, ayah_key, surah_no, ayah_no, word_index,
  block_type, block_subtype, display_order, title_ar, title_en, title_ur,
  text_ar, text_en, text_ur, data_json, source_slug, is_synthesis, register, registers_json, meta_json, status)
 VALUES ('MDB:root:نزل:sarf', 'root', 'نزل', 'نزل', '44:3', 44, 3, 2,
  'sarf', NULL, 2, 'الوزن والصرف', 'Wazn & Ṣarf', 'وزن و صرف',
  '«أَنْزَلَ» على وزن ==أَفْعَلَ== (المزيد بالهمزة). أصلُه نَزَلَ (لازمٌ: هبَط)، فأُدخِلت ==همزةُ التعدية== فصار: جعله ينزِل. المضارع يُنْزِل، والمصدر إنْزال. وفي الآية بُنِيَ الماضي على السكون لاتصاله بـ(نا)، و(نا) فاعلٌ، والهاءُ مفعولٌ به.', '«أَنْزَلَ» follows the pattern ==أَفْعَلَ== (Form IV, augmented by hamza). Its base is نَزَلَ (intransitive, “to descend”); the ==causative hamza== makes it “to make descend / send down.” Present يُنْزِل, verbal noun إنْزال. Here the perfect is built on sukūn (attached to نا, the subject), the ـه being its object.', '«أَنْزَلَ» وزن أَفْعَلَ پر (باب افعال)؛ اصل نَزَلَ (لازم)، ہمزۂ تعدیہ سے متعدی: اُتارنا۔ مضارع يُنْزِل، مصدر إنْزال۔', '{"pattern_ar":"أَفْعَلَ","from_ar":"نَزَلَ (هبَط، لازم)","to_ar":"أَنْزَلَ (أهبَط، متعدٍّ)","rule":"همزةُ التعدية: نَزَلَ الشيءُ (لازم) ← أَنْزَلَه (متعدٍّ) أي جعله ينزِل؛ المصدر إنْزال، والمضارع يُنْزِل","features":[{"k":"الوزن","v":"أَفْعَلَ"},{"k":"الصيغة","v":"فعل ماضٍ (الصيغة IV)"},{"k":"الأصل","v":"من نَزَلَ الثلاثيّ"},{"k":"المعنى الصرفي","v":"التعدية بالهمزة (الإنزال)"},{"k":"الفاعل","v":"نا (المتكلّم المعظِّم)"}]}', 'qac_morphology', 0, 'classical', '["classical","linguistic"]', '{"icon":"ruler"}', 'live');

INSERT OR REPLACE INTO qr_morph_display_blocks
 (id, scope_level, scope_key, root_ar, ayah_key, surah_no, ayah_no, word_index,
  block_type, block_subtype, display_order, title_ar, title_en, title_ur,
  text_ar, text_en, text_ur, data_json, source_slug, is_synthesis, register, registers_json, meta_json, status)
 VALUES ('MDB:root:نزل:derivations', 'root', 'نزل', 'نزل', '44:3', 44, 3, 2,
  'derivations', NULL, 3, 'الاشتقاق', 'Derived Family', 'مشتقات',
  'من (ن ز ل) أسرةٌ ثريّة: الفعلُ اللازم (نَزَلَ) ومزيداته للتعدية والتكثير والمطاوعة (أَنْزَلَ، نَزَّلَ، تَنَزَّلَ، اسْتَنْزَلَ)، والمصادرُ (تَنْزيل، إنْزال، نُزول)، وأسماءُ المكان والرُّتبة والضيافة (مَنْزِل، مَنْزِلة، نُزُل، نَزيل).', 'From ن ز ل spreads a rich family: the intransitive verb (نَزَلَ) and its augmented forms for causation, intensity and reflexivity (أَنْزَلَ, نَزَّلَ, تَنَزَّلَ, اسْتَنْزَلَ); the verbal nouns (تَنْزيل, إنْزال, نُزول); and nouns of place, rank and hospitality (مَنْزِل, مَنْزِلة, نُزُل, نَزيل).', 'ن ز ل سے بھرپور خاندان: نَزَلَ اور اس کے مزید (أَنْزَلَ، نَزَّلَ، تَنَزَّلَ، اسْتَنْزَلَ)؛ مصادر (تَنْزيل، إنْزال، نُزول)؛ اسماء (مَنْزِل، مَنْزِلة، نُزُل، نَزيل)۔', '{"groups":[{"form_ar":"الفعل — Verb","items":[{"ar":"نَزَلَ","en":"to descend, alight, lodge (I)"},{"ar":"نَزَّلَ","en":"to send down piecemeal/gradually (II)"},{"ar":"أَنْزَلَ","en":"to send down, cause to descend (IV)"},{"ar":"تَنَزَّلَ","en":"to come down in stages (V)"},{"ar":"اسْتَنْزَلَ","en":"to seek to bring down (X)"}]},{"form_ar":"المصادر — Verbal nouns","items":[{"ar":"تَنْزيل","en":"sending-down; the revelation"},{"ar":"إنْزال","en":"a sending-down (all-at-once)"},{"ar":"نُزول","en":"descent, alighting"}]},{"form_ar":"الأسماء — Nouns","items":[{"ar":"مَنْزِل","en":"dwelling; stage of a journey"},{"ar":"مَنْزِلة","en":"rank, standing, status"},{"ar":"نُزُل","en":"hospitality fare, provision for a guest"},{"ar":"نَزيل","en":"guest, lodger, resident"}]}]}', 'kmaps_five_lens', 1, 'linguistic', '["linguistic"]', '{"icon":"git-fork"}', 'live');

INSERT OR REPLACE INTO qr_morph_display_blocks
 (id, scope_level, scope_key, root_ar, ayah_key, surah_no, ayah_no, word_index,
  block_type, block_subtype, display_order, title_ar, title_en, title_ur,
  text_ar, text_en, text_ur, data_json, source_slug, is_synthesis, register, registers_json, meta_json, status)
 VALUES ('MDB:root:نزل:lexicon', 'root', 'نزل', 'نزل', '44:3', 44, 3, 2,
  'lexicon', NULL, 4, 'المعاجم', 'Classical Lexicons', 'لغات',
  '', '', '', '{"entries":[{"source":"al-Khalīl, Kitāb al-ʿAyn","death":"d. 170 AH","shade_ar":"النُّزولُ: نُزولُ القومِ بمَنزِلٍ؛ والمَنزِلُ: موضعُ النُّزول؛ والنُّزُلُ: ما هُيِّئَ للنَّزيل","shade_en":"The earliest layer is concrete and social: a travelling company halting at a stopping-place (manzil) — already tied to hospitality (nuzul, fare for the alighting guest)."},{"source":"Ibn Fāris, Maqāyīs al-Lugha","death":"d. 395 AH","shade_ar":"كلمةٌ صحيحةٌ تدلُّ على هُبوطِ شيءٍ ووُقوعِه؛ نَزَلَ عن دابّتِه، ونَزَلَ المطرُ، والنازلةُ: الشديدةُ تَنزِل","shade_en":"One governing sense — the coming-down of a thing and its landing/befalling: dismounting, rain descending, and a nāzila (calamity) that descends. Landing and striking are one idea."},{"source":"al-Rāghib, Mufradāt","death":"d. 502 AH","shade_ar":"النُّزولُ في الأصل انحطاطٌ من عُلوّ؛ والتنزيلُ يختصُّ بما نَزَلَ مُفرَّقاً مرّةً بعد أخرى، والإنزالُ عامّ","shade_en":"Descent from a height (inḥiṭāṭ min ʿuluww); tanzīl (nazzala) is reserved for what came down piecemeal, time after time, while inzāl (anzala) is general and unmarked."},{"source":"Ibn Manẓūr, Lisān al-ʿArab","death":"d. 711 AH","shade_ar":"النُّزولُ: الحُلولُ؛ نَزَلَ بهم وعليهم نُزولاً ومَنزَلاً؛ والنَّزيلُ: الضيف؛ والنُّزُلُ: ما هُيِّئَ للضيف","shade_en":"Consolidates the tradition around ḥulūl (alighting/taking up residence): the syntax of nazala with bi-/ʿalā, the dwelling and rank (manzil/manzila), the guest (nazīl), and his fare (nuzul)."}]}', 'kmaps_five_lens', 1, 'classical', '["classical"]', '{"icon":"book-open"}', 'live');

INSERT OR REPLACE INTO qr_morph_display_blocks
 (id, scope_level, scope_key, root_ar, ayah_key, surah_no, ayah_no, word_index,
  block_type, block_subtype, display_order, title_ar, title_en, title_ur,
  text_ar, text_en, text_ur, data_json, source_slug, is_synthesis, register, registers_json, meta_json, status)
 VALUES ('MDB:root:نزل:attestations', 'root', 'نزل', 'نزل', '44:3', 44, 3, 2,
  'attestations', NULL, 5, 'الاستعمال الأقدم', 'Earliest Usage', 'قدیم ترین استعمال',
  'قبل أن يصيرَ (الإنزال) تنزيلاً للوحي، عاش الجذرُ في الحسّ: نُزولُ الراكبِ ونُزولُ الغيث، والنُّزُلُ للضيف، ثم إنزالُ اللهِ الماءَ والرزقَ من السماء، فتنزيلُ الكتاب.', 'Before إنزال meant the sending-down of revelation, the root lived in the tangible: a rider dismounting, rain coming down, hospitality laid out for a guest — then God sending down water and provision, and finally the sending-down of the Book.', 'وحی کے تنزیل بننے سے پہلے جڑ حسی معنی میں: سوار کا اترنا، بارش، مہمان کا نُزُل؛ پھر اللہ کا پانی و رزق اتارنا، پھر کتاب کا تنزیل۔', '{"witnesses":[{"era_ar":"الجاهلية","era_en":"Pre-Islamic","kind_ar":"حسّي","phrase_ar":"نَزَلَ الراكبُ بالوادي","gloss_en":"the rider alighted in the valley","image_ar":"الهُبوطُ والحُلولُ بالمكان","image_en":"descending and lodging at a place","lex_source":"Kitāb al-ʿAyn","lex_ar":"نَزَلَ من عُلوٍّ إلى سُفل","lex_en":"descent from a height to a lower place","motif":"split","icon":"trending-up"},{"era_ar":"الجاهلية","era_en":"Pre-Islamic","kind_ar":"ضِيافي","phrase_ar":"أحسنَ نُزُلَه","gloss_en":"he gave him fine hospitality","image_ar":"ما يُهيَّأ للنازلِ من قِرى","image_en":"the fare prepared for one who alights","lex_source":"Lisān al-ʿArab","lex_ar":"النُّزُل: ما يُهيَّأ للضيف","lex_en":"provision readied for a guest","motif":"arrival","icon":"landmark"},{"era_ar":"الجاهلية","era_en":"Pre-Islamic","kind_ar":"اصطلاحيّ","phrase_ar":"نَزَلَ بهم المكروهُ","gloss_en":"the calamity descended upon them","image_ar":"النازلةُ: الشِّدّةُ تَنزِل بالقوم","image_en":"a nāzila — a hardship that befalls a people","lex_source":"Mir, Verbal Idioms","lex_ar":"نَزَلَ بِه: حَلَّ به المكروهُ (نزل بساحتهم)","lex_en":"the idiom “nazala bi-” = to befall (cf. 37:177)","motif":"split","icon":"quote"},{"era_ar":"قرآني","era_en":"Qurʾānic","kind_ar":"كوني","phrase_ar":"أَنْزَلَ من السماءِ ماءً","gloss_en":"He sent down water from the sky","image_ar":"إنزالُ الغيثِ والرزق","image_en":"the sending-down of rain and provision","lex_source":"Mufradāt","lex_ar":"أَنْزَلَ: عامٌّ في المُفرَّق والمجموع","lex_en":"anzala — general, all-at-once or piecemeal","motif":"shape","icon":"sunrise"},{"era_ar":"قرآني","era_en":"Qurʾānic","kind_ar":"وحيانيّ","phrase_ar":"إِنَّا أَنْزَلْنَاهُ","gloss_en":"We sent it (the Qurʾān) down","image_ar":"تنزيلُ الوحيِ من عند الله","image_en":"the sending-down of revelation from God","lex_source":"al-Burhān","lex_ar":"أُنزِل جملةً ثم نُزِّل نُجوماً","lex_en":"sent down whole, then in stages","motif":"revelation","icon":"book-open"}]}', 'kmaps_five_lens', 0, 'classical', '["classical"]', '{"icon":"landmark"}', 'live');

INSERT OR REPLACE INTO qr_morph_display_blocks
 (id, scope_level, scope_key, root_ar, ayah_key, surah_no, ayah_no, word_index,
  block_type, block_subtype, display_order, title_ar, title_en, title_ur,
  text_ar, text_en, text_ur, data_json, source_slug, is_synthesis, register, registers_json, meta_json, status)
 VALUES ('MDB:root:نزل:synthesis', 'root', 'نزل', 'نزل', '44:3', 44, 3, 2,
  'synthesis', NULL, 6, 'التخليص الجامع', 'Synthesis', 'خلاصہ',
  'تجتمعُ الخيوطُ على ==الهُبوطِ من عُلوّ==: من نُزولِ الجسمِ والغيث، إلى إنزالِ الرزق، إلى ==تنزيلِ الوحيِ== من الحكيمِ العليّ. والإنزالُ (أَنْزَلَ) نظرٌ إلى الجملةِ، والتنزيلُ (نَزَّلَ) نظرٌ إلى التفريق.', 'The strands converge on ==coming-down from a height==: from a body or rain descending, to provision sent down, to the ==sending-down of revelation== from the Wise, the Most High. anzala looks at the whole descent; nazzala at its piecemeal staging.', 'سب دھاگے بلندی سے نزول پر ملتے ہیں: جسم و بارش، پھر رزق، پھر وحی کا تنزیل۔ أَنْزَلَ کلّی نظر، نَزَّلَ تدریجی۔', '{"output":{"en":"descent → alighting → sending-down of gifts → revelation from on high","ar":"هُبوطٌ ← حُلولٌ ← إنزالُ العطاء ← تنزيلُ الوحي","ur":"نزول ← حلول ← عطا کا اتارنا ← وحی کا تنزیل"},"strands":[{"kind":"lexicon","badge":"المقاييس","source":"Ibn Fāris","ar":"هُبوطُ الشيءِ ووقوعُه","en":"the coming-down & befalling of a thing","concept":"descent","icon":"trending-up"},{"kind":"lexicon","badge":"المفردات","source":"al-Rāghib","ar":"أَنْزَلَ عامٌّ، ونَزَّلَ للمُفرَّق","en":"anzala general; nazzala = piecemeal","concept":"sending-down","icon":"split"},{"kind":"sinai","badge":"Key Terms","source":"N. Sinai","ar":"حركةٌ نازلةٌ من السماء؛ الفاعلُ اللهُ وحدَه","en":"a one-way descent from heaven — agency is God’s alone","concept":"divine descent","icon":"orbit"},{"kind":"verbal_idiom","badge":"Verbal Idioms","source":"M. Mir","ar":"نَزَلَ بِه: حلَّ به المكروه","en":"“nazala bi-” = to befall, descend upon","concept":"befalling","icon":"quote"},{"kind":"tafsir","badge":"البرهان","source":"al-Zarkashī","ar":"أُنزل جملةً ثم نُزِّل نُجوماً","en":"sent down whole, then in stages","concept":"two-stage descent","icon":"book-open"}]}', 'kmaps_synthesis', 1, 'linguistic', '["linguistic","tafsir"]', '{"icon":"sparkles"}', 'live');

INSERT OR REPLACE INTO qr_morph_display_blocks
 (id, scope_level, scope_key, root_ar, ayah_key, surah_no, ayah_no, word_index,
  block_type, block_subtype, display_order, title_ar, title_en, title_ur,
  text_ar, text_en, text_ur, data_json, source_slug, is_synthesis, register, registers_json, meta_json, status)
 VALUES ('MDB:root:نزل:kindred', 'root', 'نزل', 'نزل', '44:3', 44, 3, 2,
  'kindred', NULL, 7, 'النظائر والأضداد', 'Kindred & Contrast', 'نظائر و اضداد',
  'الإنزالُ من عائلةِ فِعلِ الوحي والعطاء النازلِ من فوق: يجاورُه الوحيُ والتنزيلُ والإيتاءُ والإلقاء؛ ويقابلُه ما صَعِدَ وارتفع: الرفعُ والعُروجُ والصعود.', 'إنزال belongs to the family of revelation and gift descending from above: near it stand waḥy, tanzīl, ītāʾ (giving), ilqāʾ (casting); against it stand what rises — rafʿ, ʿurūj, ṣuʿūd (raising, ascending).', 'إنزال وحی و عطا کے خاندان سے جو اوپر سے اترتا ہے: نظائر وحی، تنزیل، ایتاء، القاء؛ اضداد رفع، عروج، صعود۔', '{"synonyms":[{"ar":"وَحْي","en":"waḥy","note":"inspiration/communication cast into the heart"},{"ar":"تَنْزيل","en":"tanzīl","note":"the piecemeal sending-down of the Book"},{"ar":"إيتاء","en":"ītāʾ","note":"the giving/granting of scripture (آتينا)"},{"ar":"إلْقاء","en":"ilqāʾ","note":"casting speech upon the Prophet (نُلقي عليك)"}],"contrast":[{"ar":"رَفْع","en":"raising","note":"lifting up vs. sending down (رافعك إليّ)"},{"ar":"عُروج / صُعود","en":"ascending","note":"mounting upward (تعرج الملائكة)"}]}', 'kmaps_five_lens', 1, 'linguistic', '["linguistic"]', '{"icon":"scale"}', 'live');

INSERT OR REPLACE INTO qr_morph_display_blocks
 (id, scope_level, scope_key, root_ar, ayah_key, surah_no, ayah_no, word_index,
  block_type, block_subtype, display_order, title_ar, title_en, title_ur,
  text_ar, text_en, text_ur, data_json, source_slug, is_synthesis, register, registers_json, meta_json, status)
 VALUES ('MDB:root:نزل:metaphor', 'root', 'نزل', 'نزل', '44:3', 44, 3, 2,
  'metaphor', NULL, 8, 'التصوير الذهني', 'Conceptual Metaphor', 'تصور',
  'الاستعارةُ الجذرية: ==الوحيُ نُزولٌ من عُلوّ==. فالكلامُ الإلهيُّ يأتي من مصدرٍ عالٍ مُتعالٍ إلى الأرض والقلب — محورٌ رأسيٌّ يصِلُ السماءَ بالإنسان، ويجعلُ التلقّي هبوطاً للنور.', 'The root metaphor: ==REVELATION IS A DESCENT FROM ON HIGH==. Divine speech comes from a high, transcendent source down to earth and the heart — a vertical axis joining sky to human. For Izutsu this “sending-down” of the āyāt is the very ==start of the God–man relationship==; for Sinai it is a one-way divine prerogative — descent, never the Prophet’s ascent (cf. 17:93).', 'بنیادی استعارہ: وحی بلندی سے نزول — کلامِ الٰہی عالی ماخذ سے دل و زمین تک اترتا ہے۔', '{"source_ar":"الهُبوطُ من السماء","target_ar":"مجيءُ الوحيِ من الله إلى الناس","mapping":"REVELATION IS A DESCENT FROM ON HIGH"}', 'kmaps_five_lens', 1, 'linguistic', '["linguistic"]', '{"icon":"git-compare"}', 'live');

INSERT OR REPLACE INTO qr_morph_display_blocks
 (id, scope_level, scope_key, root_ar, ayah_key, surah_no, ayah_no, word_index,
  block_type, block_subtype, display_order, title_ar, title_en, title_ur,
