 VALUES ('MDB:root:نزل:constellation', 'root', 'نزل', 'نزل', '44:3', 44, 3, 2,
  'constellation', NULL, 9, 'كوكبة الكلمة', 'Word Constellation', 'کوکبہ',
  'يدورُ حول (أَنْزَلَ) مشتقّاتُه القريبة (نَزَّلَ، تَنْزيل، تَنَزَّلَ، مُنَزَّل) في المدار الأول، ثم حقلُ الوحيِ والعطاء (وحي، كتاب، ماء) في الثاني، ويقابلُه الصعودُ (رفع، عُروج).', 'Around أَنْزَلَ orbit its near derivatives (نَزَّلَ, تَنْزيل, تَنَزَّلَ, مُنَزَّل) in the first ring, then the field of revelation and gift (waḥy, kitāb, rain) in the second, with ascent (rafʿ, ʿurūj) opposite.', 'أَنْزَلَ کے گرد قریبی مشتقات (نَزَّلَ، تَنْزيل، تَنَزَّلَ، مُنَزَّل)، پھر وحی و عطا کا میدان، اور مقابل میں صعود۔', '{"center":{"ar":"أَنْزَلَ","root":"ن ز ل"},"nodes":[{"ar":"نَزَّلَ","en":"sent down (gradual)","ring":1,"angle":20,"kind":"derivative"},{"ar":"تَنْزيل","en":"the revelation","ring":1,"angle":80,"kind":"derivative"},{"ar":"تَنَزَّلَ","en":"came down in stages","ring":1,"angle":145,"kind":"derivative"},{"ar":"مُنَزَّل","en":"sent-down","ring":1,"angle":210,"kind":"derivative"},{"ar":"وَحْي","en":"inspiration","ring":2,"angle":55,"kind":"kindred"},{"ar":"كِتاب","en":"the Book","ring":2,"angle":120,"kind":"kindred"},{"ar":"رَفْع","en":"raising","ring":2,"angle":300,"kind":"contrast"},{"ar":"عُروج","en":"ascending","ring":2,"angle":340,"kind":"contrast"}]}', 'kmaps_five_lens', 1, 'linguistic', '["linguistic"]', '{"icon":"orbit"}', 'live');

INSERT OR REPLACE INTO qr_morph_display_blocks
 (id, scope_level, scope_key, root_ar, ayah_key, surah_no, ayah_no, word_index,
  block_type, block_subtype, display_order, title_ar, title_en, title_ur,
  text_ar, text_en, text_ur, data_json, source_slug, is_synthesis, register, registers_json, meta_json, status)
 VALUES ('MDB:root:نزل:occurrences', 'root', 'نزل', 'نزل', '44:3', 44, 3, 2,
  'occurrences', NULL, 10, 'الشواهد القرآنية', 'Qurʾānic Occurrences', 'قرآنی شواہد',
  'يردُ الجذرُ نحوَ ٢٩٣ مرّةً في حقولٍ متضامّة: تنزيلُ الوحي، وإنزالُ الرزقِ والماء، والنُّزولُ الحسّيّ، ونُزولُ العذاب. وموضعُ الدراسة هنا: «إِنَّا أَنْزَلْنَاهُ فِي لَيْلَةٍ مُبَارَكَةٍ».', 'The root occurs ~293 times across kindred fields — the sending-down of revelation, of provision and water, physical alighting, and the descent of affliction. The study locus here is «We sent it down on a blessed night».', 'جڑ تقریباً ۲۹۳ بار: وحی کا تنزیل، رزق و پانی کا انزال، حسی نزول، عذاب کا نزول۔ مطالعہ: «إِنَّا أَنْزَلْنَاهُ فِي لَيْلَةٍ مُبَارَكَةٍ»۔', '{"items":[{"ayah_key":"44:3","kind_ar":"إنزالُ الكتاب","en":"the Book sent down","motif":"revelation","text_ar":"إِنَّا أَنْزَلْنَاهُ فِي لَيْلَةٍ مُبَارَكَةٍ","note":"إنزالُ القرآنِ جملةً في الليلةِ المباركة — جوابُ القسم بالكتاب المبين","note_en":"The Qurʾān sent down whole on the blessed night — the answer to the oath by the clarifying Book (44:2).","focus":true,"icon":"star"},{"ayah_key":"2:185","kind_ar":"شهرُ الإنزال","en":"the month of revelation","motif":"arrival","text_ar":"شَهْرُ رَمَضَانَ الَّذِي أُنْزِلَ فِيهِ الْقُرْآنُ","note":"رمضانُ ظرفُ إنزالِ القرآن، هُدًى للناس","note_en":"Ramadan as the vessel of the Qurʾān’s descent — guidance for humankind.","icon":"book-open"},{"ayah_key":"6:99","kind_ar":"إنزالُ الماء","en":"sending down water","motif":"shape","text_ar":"وَهُوَ الَّذِي أَنْزَلَ مِنَ السَّمَاءِ مَاءً","note":"النُّزولُ الكونيّ — إنزالُ الغيثِ سببِ الحياة","note_en":"The creational descent — rain sent down as the cause of life.","icon":"sunrise"},{"ayah_key":"25:32","kind_ar":"التنزيلُ المُنجَّم","en":"the staged sending-down","motif":"split","text_ar":"لَوْلَا نُزِّلَ عَلَيْهِ الْقُرْآنُ جُمْلَةً وَاحِدَةً","note":"اعتراضُهم على التفريق — و«نَزَّلَ» للتنزيلِ المُنجَّم مقابلَ «أَنْزَلَ» الجُمليّ","note_en":"Their objection to piecemeal delivery — nazzala marks the staged descent against the all-at-once anzala.","icon":"split"}]}', NULL, 0, 'quran', '["quran"]', '{"icon":"map-pin"}', 'live');

INSERT OR REPLACE INTO qr_morph_display_blocks
 (id, scope_level, scope_key, root_ar, ayah_key, surah_no, ayah_no, word_index,
  block_type, block_subtype, display_order, title_ar, title_en, title_ur,
