 VALUES ('MDB:root:نزل:development', 'root', 'نزل', 'نزل', '44:3', 44, 3, 2,
  'development', NULL, 11, 'التطور الدلالي', 'Semantic Development', 'ارتقائے معنی',
  'يمشي المعنى من الحسّ إلى الوحي: الهُبوطُ ثم الحُلولُ والضيافةُ ثم إنزالُ العطاءِ من السماء ثم تنزيلُ الكتاب.', 'The sense travels from the tangible to revelation: descending → alighting/hospitality → sending down gifts from the sky → the sending-down of the Book.', 'معنی حس سے وحی تک: ہبوط ← حلول و ضیافت ← عطا کا انزال ← کتاب کا تنزیل۔', '{"stages":[{"label_ar":"الهُبوط","label_en":"Descending","note":"نَزَلَ من عُلوٍّ إلى سُفل — نُزولُ الجسمِ والغيث"},{"label_ar":"الحُلول","label_en":"Alighting","note":"نَزَلَ بالقوم — المَنزِلُ والنُّزُلُ والضيافة"},{"label_ar":"الإنزال","label_en":"Sending-down","note":"أَنْزَلَ اللهُ من السماءِ ماءً ورزقاً ولباساً"},{"label_ar":"التنزيل","label_en":"Revelation","note":"أَنْزَلْنَا الكتابَ — تنزيلُ الوحيِ المُبين"}]}', 'kmaps_five_lens', 1, 'linguistic', '["linguistic"]', '{"icon":"trending-up"}', 'live');

INSERT OR REPLACE INTO qr_morph_display_blocks
 (id, scope_level, scope_key, root_ar, ayah_key, surah_no, ayah_no, word_index,
