 VALUES ('MDB:root:نزل:usage_map', 'root', 'نزل', 'نزل', '44:3', 44, 3, 2,
  'usage_map', NULL, 12, 'خريطة الاستعمال', 'Usage Map', 'نقشۂ استعمال',
  'توزُّعُ معاني (أنزل) عبر مواضعه: تنزيلُ الوحي، وإنزالُ الرزق، والنُّزولُ الحسّيّ، ونُزولُ العذاب.', 'How أنزل’s senses distribute across its verses: revelation, provision, physical alighting, affliction.', 'أنزل کے معانی کی تقسیم: وحی، رزق، حسی نزول، عذاب۔', '{"axes":[{"ar":"تنزيلُ الوحي","en":"Revelation"},{"ar":"إنزالُ الرزق","en":"Provision"},{"ar":"نُزولٌ حسّيّ","en":"Alighting"},{"ar":"نُزولُ العذاب","en":"Affliction"}],"rows":[{"ref":"44:3","label":"إنّا أنزلناه","weights":[3,0,0,0]},{"ref":"2:185","label":"أُنزل القرآن","weights":[3,0,0,0]},{"ref":"6:99","label":"أنزل ماءً","weights":[0,3,0,0]},{"ref":"7:26","label":"أنزلنا لباسًا","weights":[0,3,0,0]},{"ref":"2:57","label":"أنزلنا المنّ","weights":[0,3,0,0]},{"ref":"2:59","label":"أنزلنا رجزًا","weights":[0,0,0,3]}]}', 'kmaps_usage_map', 1, 'quran', '["quran"]', '{"icon":"grid-3x3"}', 'live');

INSERT OR REPLACE INTO qr_morph_display_blocks
 (id, scope_level, scope_key, root_ar, ayah_key, surah_no, ayah_no, word_index,
  block_type, block_subtype, display_order, title_ar, title_en, title_ur,
  text_ar, text_en, text_ur, data_json, source_slug, is_synthesis, register, registers_json, meta_json, status)
 VALUES ('MDB:root:نزل:master_story', 'root', 'نزل', 'نزل', '44:3', 44, 3, 2,
  'master_story', NULL, 13, 'القصة الجامعة', 'Master Story', 'جامع کہانی',
  'قصةُ (نزل) في أربع حركات: الهُبوطُ، فالحُلولُ، فالإنزالُ، فتنزيلُ الكتاب.', 'The story of نزل in four movements: descending, then alighting, then sending-down, then the revelation of the Book.', 'نزل کی کہانی چار حرکتوں میں۔', '{"medallion_ar":"أَنْزَلَ","medallion_root":"ن ز ل","threads":["المعجم","الاشتقاق","التفسير"],"movements":[{"no":"I","motif":"descent","en":"The Descent","ar":"الهُبوط","accent":"#c9a84c","text":"كان النُّزولُ أوّلاً ==هُبوطاً محسوساً==: يهبطُ الراكبُ عن دابّتِه، ويهبطُ الغيثُ من السحاب. وضمَّ ابنُ فارسٍ إلى الهبوطِ معنى الوقوع، فالنازلةُ شِدّةٌ تَنزِل — وأصلُ المادّةِ عنده: هُبوطُ شيءٍ ووقوعُه.","text_en":"At first نزول was a ==descent you could see==: the rider comes down from his mount, the rain comes down from the cloud. Ibn Fāris joins to “descent” the sense of befalling — a nāzila is a hardship that “comes down” — his one root sense: the coming-down of a thing and its landing.","icon":"trending-up","chips":[{"ar":"نُزول","en":"descent"}]},{"no":"II","motif":"alighting","en":"The Alighting","ar":"الحُلول","accent":"#7fb58f","text":"ثم صار الهبوطُ ==حُلولاً==: نَزَلَ بالقومِ فحلَّ بينهم ضيفاً، فنشأ المَنزِلُ موضعاً، والنُّزُلُ قِرًى للضيف، والمَنزِلةُ رُتبةً ومكانة. وعلى الحُلولِ والإقامةِ بنى ابنُ منظورٍ المادّةَ كلَّها.","text_en":"Then descent became ==alighting==: to nazala among a people was to lodge with them as a guest — so manzil became a place, nuzul the fare for a guest, and manzila a rank and standing. Ibn Manẓūr builds the whole root on ḥulūl, taking up residence.","icon":"landmark","chips":[{"ar":"مَنزِل","en":"dwelling"}]},{"no":"III","motif":"sending","en":"The Sending-Down","ar":"الإنزال","accent":"#8878e2","text":"وعدَّت ==همزةُ الإنزال== الفعلَ، فصار اللهُ هو المُنزِل: أنزلَ من السماءِ ماءً ورزقاً ولباساً وحديداً وسكينةً. فالجذرُ يخدمُ الوحيَ والطبيعةَ معاً — نعمةٌ تهبطُ من عُلوٍّ على الخلق.","text_en":"The ==causative hamza== of inzāl made it transitive, so God is the Sender-down: He sent down from the sky water, provision, raiment, iron, and serenity. The root serves both revelation and nature — a grace descending from on high upon creation.","icon":"sunrise","chips":[{"ar":"أنزل ماءً","en":"sent down water"}]},{"no":"IV","motif":"revelation","en":"The Revelation","ar":"التنزيل","accent":"#93b8d6","text":"وبلغَ الجذرُ ذروتَه في ==تنزيلِ الكتاب==: «إنّا أنزلناه في ليلةٍ مباركة» — إنزالٌ من عُلوٍّ لا صُعودَ فيه، الفاعلُ اللهُ وحدَه. واختيرَ «أنزل» للجملةِ دون «نزّل» للتفريق؛ فالوحيُ عند سيناء حركةٌ نازلةٌ من السماء لا يملكُها إلا المُنزِل.","text_en":"And the root reached its summit in the ==sending-down of the Book==: «We sent it down on a blessed night» — a descent from on high with no ascent in it, God its sole agent. anzala (the whole) is chosen over nazzala (the piecemeal); for Sinai, revelation is a downward movement from heaven that only the Sender-down commands.","icon":"book-open","chips":[{"ar":"أنزلناه","en":"We sent it down"}]}]}', 'kmaps_master_story', 1, 'linguistic', '["linguistic","tafsir"]', '{"icon":"sparkles"}', 'live');

INSERT OR REPLACE INTO qr_morph_display_blocks
 (id, scope_level, scope_key, root_ar, ayah_key, surah_no, ayah_no, word_index,
  block_type, block_subtype, display_order, title_ar, title_en, title_ur,
  text_ar, text_en, text_ur, data_json, source_slug, is_synthesis, register, registers_json, meta_json, status)
 VALUES ('MDB:ctx:نزل:44:3:irab', 'context', '44:3', 'نزل', '44:3', 44, 3, 2,
  'irab', NULL, 1, 'الإعراب في السياق', 'Iʿrāb in Context', 'اعراب',
  '«أَنْزَلْنَاهُ» ==فعلٌ ماضٍ== مبنيٌّ على السكون لاتّصالِه بـ«نا»، و«نا» ==فاعلٌ== في محلّ رفع، والهاءُ ==مفعولٌ به== يعودُ على القرآن. وجملةُ «أنزلناه» في محلّ رفع ==خبرُ إنّ==، وهي ==جوابُ القسم== المتقدّم في «وَالْكِتَابِ الْمُبِينِ». و«في ليلةٍ» متعلّقان بأنزلنا، و«مباركةٍ» نعت.', '«أَنْزَلْنَاهُ» is a ==perfect verb== built on sukūn (attached to نا); «نا» is its ==subject== and the «ـه» its ==object==, referring back to the Qurʾān. The clause stands as the ==predicate of إنّ== and is the ==response to the oath== sworn in «by the clarifying Book» (44:2). «في ليلة» attaches to anzalnā; «mubāraka» is its adjective.', '«أَنْزَلْنَاهُ» فعل ماضٍ، «نا» فاعل، «ـه» مفعول به (قرآن)؛ جملہ خبرِ إنّ اور جوابِ قسم (44:2)؛ «في ليلة» متعلق، «مباركة» نعت۔', '{"role_ar":"فعلٌ ماضٍ (الهاءُ مفعولٌ به يعودُ على القرآن)","role_en":"perfect verb — the ـه is its object (the Qurʾān)","position_ar":"نا الفاعلين فاعلٌ؛ وجملةُ «أنزلناه» في محلّ رفع خبرُ إنّ، وهي جوابُ القسم","sign_ar":"مبنيٌّ على السكون","sources":["الإعراب الميسّر: «أنزلناه» فعلٌ ماضٍ، و«نا» فاعل، والهاءُ مفعولٌ به، والجملةُ خبرُ إنّ؛ و«في ليلة» جارٌّ ومجرور متعلّقان بأنزلناه، و«مباركة» نعتٌ لليلة، وجملةُ «إنّا أنزلناه» جوابُ القسم","التبيان (العُكبري): «إنّا أنزلناه» هو جوابُ القسم، و«إنّا كنّا» مستأنَف"]}', 'muyassar_irab', 0, 'classical', '["classical"]', '{"icon":"waypoints"}', 'live');

INSERT OR REPLACE INTO qr_morph_display_blocks
 (id, scope_level, scope_key, root_ar, ayah_key, surah_no, ayah_no, word_index,
  block_type, block_subtype, display_order, title_ar, title_en, title_ur,
  text_ar, text_en, text_ur, data_json, source_slug, is_synthesis, register, registers_json, meta_json, status)
 VALUES ('MDB:ctx:نزل:44:3:balagha', 'context', '44:3', 'نزل', '44:3', 44, 3, 2,
  'balagha', NULL, 2, 'البلاغة', 'Balāgha', 'بلاغت',
  'عبّر بـ«أَنْزَلْنَاهُ» لا «نَزَّلْناه»: فعند الراغبِ والزمخشريّ ==الإنزالُ للجملةِ دُفعةً== والتنزيلُ للتفريق، وهو مناسبٌ لإنزالِه في الليلةِ المباركة؛ وذهبَ أبو حيّانَ (ومعه سيناء حديثاً) إلى ==ترادُفهما==. وضميرُ «إنّا» ==جمعُ التعظيم==، والجملةُ جوابُ القسمِ بالكتابِ تفخيماً؛ والوحيُ ==نُزولٌ لا صُعود== (ردًّا على «حتى تُنزِّلَ علينا كتاباً»).', 'The choice of «anzalnāhu» over «nazzalnāhu»: for al-Rāghib and al-Zamakhsharī ==inzāl is the all-at-once== descent and tanzīl the piecemeal — fitting the blessed-night sending; Abū Ḥayyān (and, in modern terms, Sinai) hold the two ==synonymous==. The «We» is the ==plural of majesty==, the clause the answer to the oath by the Book. Revelation is ==descent, not ascent== — rebutting the demand that the Prophet “bring a Book down” (17:93).', '«أنزلناه» بمقابل «نزّلناه»: راغب و زمخشری کے نزدیک إنزال یکبارگی، تنزیل تدریجی؛ ابو حیان و سیناء کے نزدیک مترادف۔ «إنّا» جمعِ تعظیم؛ وحی نزول ہے نہ صعود۔', '{"formula_ar":"إنزالٌ جُمليّ (أَنْزَلَ) + ضميرُ التعظيم (إنّا) + جوابُ قسم","formula_en":"the all-at-once anzala + the majestic “We” + the oath-answer — dignifying the Book’s descent","refs":["97:1","2:185","25:32","17:93","3:3","44:2"]}', 'kmaps_five_lens', 1, 'modern', '["modern"]', '{"icon":"feather"}', 'live');

INSERT OR REPLACE INTO qr_morph_display_blocks
 (id, scope_level, scope_key, root_ar, ayah_key, surah_no, ayah_no, word_index,
  block_type, block_subtype, display_order, title_ar, title_en, title_ur,
  text_ar, text_en, text_ur, data_json, source_slug, is_synthesis, register, registers_json, meta_json, status)
 VALUES ('MDB:ctx:نزل:44:3:translators', 'context', '44:3', 'نزل', '44:3', 44, 3, 2,
  'translators', NULL, 3, 'خيارات المترجمين', 'Translator Choices', 'مترجمین کے اختیارات',
  'يتوزّعُ المترجمون بين إبرازِ ==الإرسالِ من فوق== (sent down / from on high) وبين ==الإيحاء== (revealed): كلاهما يحاولُ نقلَ صورةِ النُّزول.', 'Translators split between foregrounding the ==downward sending== (“sent down,” “from on high”) and the act of ==revealing== — each trying to carry the descent-image across.', 'مترجمین «اوپر سے اتارنا» اور «وحی کرنا» کے درمیان: دونوں نزول کی تصویر منتقل کرتے ہیں۔', '{"renderings":[{"translator":"Pickthall","text":"Lo! We revealed it on a blessed night","reading":"revealed"},{"translator":"Yusuf Ali","text":"We sent it down during a blessed night","reading":"sent down"},{"translator":"Arberry","text":"We sent it down in a blessed night","reading":"sent down"},{"translator":"Saheeh Intl","text":"Indeed, We sent it down during a blessed night","reading":"sent down"},{"translator":"Muhammad Asad","text":"We have indeed bestowed it from on high on a blessed night","reading":"from on high"}]}', 'kmaps_translations', 0, 'modern', '["modern"]', '{"icon":"languages"}', 'live');

INSERT OR REPLACE INTO qr_morph_display_blocks
 (id, scope_level, scope_key, root_ar, ayah_key, surah_no, ayah_no, word_index,
  block_type, block_subtype, display_order, title_ar, title_en, title_ur,
  text_ar, text_en, text_ur, data_json, source_slug, is_synthesis, register, registers_json, meta_json, status)
 VALUES ('MDB:ctx:نزل:44:3:tafsir', 'context', '44:3', 'نزل', '44:3', 44, 3, 2,
  'tafsir', NULL, 4, 'التفسير', 'Tafsīr & Scholars', 'تفسیر',
  'الضميرُ في «أنزلناه» للقرآن (المذكورِ بالكتابِ المبين)؛ والليلةُ المباركةُ ==ليلةُ القدر== في رمضان؛ أُنزل القرآنُ فيها ==جملةً واحدة== إلى سماء الدنيا (بيتِ العزّة)، ثم نُزِّل مُنجَّماً على النبيّ ﷺ.', 'The pronoun in «anzalnāhu» is the Qurʾān (named by “the clarifying Book”); the blessed night is ==Laylat al-Qadr== in Ramadan (mid-Shaʿbān is a weak minority view). The mainstream reads a ==two-stage descent==: all at once to the earthly heaven (Bayt al-ʿIzza), then in stages to the Prophet ﷺ. ==Ibn ʿĀshūr dissents==, reading «anzalnāhu» as the mere *onset* of the gradual revelation.', '«أنزلناه» کی ضمیر قرآن؛ ليلة مباركة ليلة القدر رمضان میں؛ قرآن یکبارگی آسمانِ دنیا (بیت العزّہ) اتارا گیا، پھر تدریجاً نبی ﷺ پر۔', '{"entries":[{"scholar":"al-Ṭabarī","work":"Jāmiʿ al-Bayān","text":"أُنزِلَ القرآنُ كلُّه إلى السماءِ الدنيا في هذه الليلةِ، ثم أُنزِلَ نَجْماً نَجْماً في سائرِ الأيام؛ والليلةُ المباركةُ ليلةُ القدر.","text_en":"The whole Qurʾān was sent down to the lowest heaven on this night, then sent down star-by-star over the remaining days; the blessed night is Laylat al-Qadr.","text_ur":"پورا قرآن اس رات آسمانِ دنیا پر اتارا گیا، پھر باقی ایام میں تھوڑا تھوڑا؛ اور مبارک رات لیلۃ القدر ہے۔"},{"scholar":"al-Zamakhsharī","work":"al-Kashshāf","text":"أُنزِلَ جملةً واحدةً إلى السماءِ الدنيا، وكان جبريلُ عليه السلام يُنزِّلُه على رسولِ اللهِ ﷺ نُجوماً نُجوماً.","text_en":"It was sent down all at once to the lowest heaven, and Gabriel used to bring it down upon the Messenger ﷺ portion by portion.","text_ur":"یکبارگی آسمانِ دنیا پر اتارا گیا، اور جبریل علیہ السلام اسے رسول اللہ ﷺ پر تھوڑا تھوڑا اتارتے رہے۔"},{"scholar":"al-Rāzī","work":"Mafātīḥ al-Ghayb","text":"نزَل القرآنُ جملةً من اللوحِ المحفوظِ إلى البيتِ المعمورِ وهو في السماءِ الدنيا، ثم نزَل في أنواعِ الوقائعِ حالاً فحالاً؛ والليلةُ ليلةُ القدر، ومَن قال ليلةَ النصفِ من شعبان فلا دليلَ يُعوَّلُ عليه.","text_en":"The Qurʾān descended whole from the Preserved Tablet to al-Bayt al-Maʿmūr in the lowest heaven, then descended according to events, state by state; the night is Laylat al-Qadr — those who say mid-Shaʿbān have no reliable proof.","text_ur":"قرآن لوحِ محفوظ سے البیت المعمور (آسمانِ دنیا) میں یکجا اترا، پھر واقعات کے مطابق حالاً فحالاً؛ رات لیلۃ القدر ہے، اور نصفِ شعبان کہنے والوں کی کوئی معتبر دلیل نہیں۔"},{"scholar":"Ibn Kathīr","work":"Tafsīr al-Qurʾān al-ʿAẓīm","text":"أنزلَ اللهُ القرآنَ كلَّه في ليلةِ القدرِ من أمِّ الكتابِ إلى بيتِ العِزّةِ في سماءِ الدنيا، ثم أنزلَه على نبيِّه ﷺ؛ ومَن قال إنها ليلةُ النصفِ من شعبان فقد أبعدَ النَّجْعة.","text_en":"God sent the whole Qurʾān down on Laylat al-Qadr from the Umm al-Kitāb to Bayt al-ʿIzza in the lowest heaven, then sent it down upon His Prophet ﷺ; whoever says it is mid-Shaʿbān has strayed far afield.","text_ur":"اللہ نے پورا قرآن لیلۃ القدر میں امّ الکتاب سے بیت العزّہ (آسمانِ دنیا) اتارا، پھر نبی ﷺ پر؛ اور جو کہے کہ یہ نصفِ شعبان کی رات ہے وہ حق سے بہت دور گیا۔"},{"scholar":"al-Ālūsī","work":"Rūḥ al-Maʿānī","text":"«إنّا أنزلناه» أي الكتابَ المبينَ الذي هو القرآنُ على القولِ المُعوَّلِ عليه؛ والمرادُ إنزالُه في تلك الليلةِ جملةً إلى السماء الدنيا من اللوح، ثم الإنزالُ المُنجَّمُ في ثلاثٍ وعشرين سنة — وعليه أكثرُ المفسّرين والظواهرُ معهم.","text_en":"«We sent it down» — the clarifying Book, the Qurʾān on the relied-upon view; its sending on that night means its all-at-once descent to the lowest heaven from the Tablet, then the piecemeal sending over 23 years — the view of most exegetes, the plain texts with them.","text_ur":"«إنا أنزلناه» یعنی الكتاب المبين جو قرآن ہے، معتمد قول پر؛ اس رات نزول سے مراد لوح سے آسمانِ دنیا تک یکبارگی، پھر تئیس سال میں تدریجی — اکثر مفسرین اسی پر، ظواہر بھی موافق۔"},{"scholar":"Ibn ʿĀshūr","work":"al-Taḥrīr wa-l-Tanwīr","text":"المرادُ بالكتابِ القرآن؛ ومعنى الفعلِ في «أنزلناه» ابتداءُ إنزالِه، فكلُّ آيةٍ تنزِل مُنضمّةٌ إليه انضمامَ الجزءِ للكلّ حتى تمّ نزولُ آخرِ آية؛ والليلةُ ليلةُ القدرِ في العَشْرِ الأواخر، وقولُ عكرمةَ إنها ليلةُ النصفِ من شعبان ضعيف.","text_en":"The “Book” is the Qurʾān; the verb «We sent it down» means the onset of its sending — each descending āya joined to it as part to whole, until the last āya came down; the night is Laylat al-Qadr in the last ten, and ʿIkrima’s mid-Shaʿbān view is weak.","text_ur":"کتاب سے مراد قرآن؛ «أنزلناه» میں فعل کا معنی نزول کی ابتدا — ہر اترتی آیت جزو کی کل سے پیوستگی کی طرح، یہاں تک کہ آخری آیت اتری؛ رات لیلۃ القدر عشرۂ اخیرہ میں، اور عکرمہ کا نصفِ شعبان کہنا ضعیف ہے۔"}]}', 'TABARI', 0, 'tafsir', '["tafsir"]', '{"icon":"quote"}', 'live');

